export type Match = {
  /** CoStar commercial listing id, from commercial-listing-summary.jsonl in the kit. */
  listingId: number;
  address: string;
  /** Suite or building name, then the city. */
  detail: string;
  /** Listing photo on CoStar's CDN. It serves browsers only, so it cannot go through the Next image optimizer. */
  photo: string;
  squareFeet: number;
  /** Asking rent in dollars per square foot per year, triple net. */
  rentPerSquareFootYear: number;
  /** 0 to 100. A placeholder until the matching agent scores spaces against the brief. */
  confidence: number;
};

const photo = (key: string) => `https://ahprd1cdn.csgpimgs.com/i2/${key}/113/image.jpg`;

