import type { Metadata } from "next";
import Image from "next/image";
import { MATCHES, monthlyRent } from "../lib/matches";

export const metadata: Metadata = {
  title: "Matches · Foreground",
};

const number = new Intl.NumberFormat("en-US");

export default function MatchesPage() {
  const matches = [...MATCHES].sort((a, b) => b.confidence - a.confidence);

  return (
    <>
      <header className="animate-rise">
        <h1 className="text-[clamp(1.6rem,4vw,2.5rem)] font-medium leading-tight tracking-tight">Your matches</h1>
        <p className="mt-2 text-foreground/50">{matches.length} spaces, best fit first.</p>
      </header>

      <ul className="mt-14 grid grid-cols-[repeat(auto-fit,minmax(min(100%,18rem),1fr))] gap-x-10 gap-y-16">
        {matches.map((match, index) => (
          <li key={match.listingId} className="animate-rise" style={{ animationDelay: `${120 + index * 90}ms` }}>
            <article>
              <div className="relative aspect-[4/3] overflow-hidden rounded-2xl bg-foreground/5">
                <Image
                  src={match.photo}
                  alt={`Exterior of ${match.address}`}
                  fill
                  unoptimized
                  sizes="(min-width: 768px) 33vw, 100vw"
                  className="object-cover"
                />
              </div>

              <div className="mt-5 flex items-baseline justify-between gap-4">
                <div className="min-w-0">
                  <h2 className="truncate text-lg font-medium tracking-tight">{match.address}</h2>
                  <p className="mt-0.5 text-sm text-foreground/45">{match.detail}</p>
                </div>
                <p className="shrink-0 text-right tabular-nums">
                  <span className="text-lg font-medium text-accent">{match.confidence}%</span>
                  <span className="mt-0.5 block text-xs text-foreground/45">confidence</span>
                </p>
              </div>

              <dl className="mt-6 flex gap-10 text-sm">
                <div>
                  <dt className="text-foreground/45">Price</dt>
                  <dd className="mt-1 tabular-nums">${number.format(monthlyRent(match))}/mo</dd>
                </div>
                <div>
                  <dt className="text-foreground/45">Size</dt>
                  <dd className="mt-1 tabular-nums">{number.format(match.squareFeet)} sq ft</dd>
                </div>
              </dl>
            </article>
          </li>
        ))}
      </ul>
    </>
  );
}
